package com.purewo.cyberstream

import android.content.Intent
import android.net.Uri
import androidx.activity.result.ActivityResult
import com.getcapacitor.JSObject
import com.getcapacitor.Plugin
import com.getcapacitor.PluginCall
import com.getcapacitor.PluginMethod
import com.getcapacitor.annotation.ActivityCallback
import com.getcapacitor.annotation.CapacitorPlugin

/**
 * Capacitor bridge for the Android Media3 player.
 *
 * The WebView owns login cookies and therefore prepares ticketed URLs before
 * calling this plugin. The native side only receives an opaque playback
 * session and never persists or inspects the user's authenticated cookie.
 */
@CapacitorPlugin(name = "CyberPlayer")
class CyberPlayerPlugin : Plugin() {
    companion object {
        @Volatile
        private var activePlugin: CyberPlayerPlugin? = null

        fun emitProgress(
            sessionId: String,
            resourceId: String,
            positionMs: Long,
            durationMs: Long,
            state: String,
        ) {
            activePlugin?.publishProgress(sessionId, resourceId, positionMs, durationMs, state)
        }
    }

    override fun load() {
        super.load()
        activePlugin = this
    }

    override fun handleOnDestroy() {
        if (activePlugin === this) activePlugin = null
        super.handleOnDestroy()
    }

    @PluginMethod
    fun open(call: PluginCall) {
        val session = call.getObject("session")
        if (session == null) {
            call.reject("Missing playback session")
            return
        }

        val intent = Intent(activity, PlayerActivity::class.java)
            .putExtra(PlayerActivity.EXTRA_SESSION_JSON, session.toString())
        startActivityForResult(call, intent, "handlePlayerResult")
    }

    @ActivityCallback
    private fun handlePlayerResult(call: PluginCall, result: ActivityResult) {
        val data = result.data
        val payload = JSObject()
        payload.put("sessionId", data?.getStringExtra(PlayerActivity.RESULT_SESSION_ID) ?: "")
        payload.put("resourceId", data?.getStringExtra(PlayerActivity.RESULT_RESOURCE_ID))
        payload.put("positionMs", data?.getLongExtra(PlayerActivity.RESULT_POSITION_MS, 0L) ?: 0L)
        payload.put("durationMs", data?.getLongExtra(PlayerActivity.RESULT_DURATION_MS, 0L) ?: 0L)
        payload.put("ended", data?.getBooleanExtra(PlayerActivity.RESULT_ENDED, false) ?: false)
        payload.put("authExpired", data?.getBooleanExtra(PlayerActivity.RESULT_AUTH_EXPIRED, false) ?: false)
        payload.put("error", data?.getStringExtra(PlayerActivity.RESULT_ERROR))
        call.resolve(payload)
    }

    @PluginMethod
    fun openExternalUrl(call: PluginCall) {
        val rawUrl = call.getString("url")
        if (rawUrl.isNullOrBlank()) {
            call.reject("Missing URL")
            return
        }

        try {
            val intent = if (rawUrl.startsWith("intent:")) {
                Intent.parseUri(rawUrl, Intent.URI_INTENT_SCHEME)
            } else {
                Intent(Intent.ACTION_VIEW, Uri.parse(rawUrl))
            }
            intent.component = null
            if (intent.resolveActivity(activity.packageManager) == null) {
                call.reject("No Android application can handle this URL")
                return
            }
            activity.startActivity(intent)
            call.resolve()
        } catch (error: Exception) {
            call.reject("Unable to open external URL", error)
        }
    }

    private fun publishProgress(
        sessionId: String,
        resourceId: String,
        positionMs: Long,
        durationMs: Long,
        state: String,
    ) {
        notifyListeners(
            "progress",
            JSObject().apply {
                put("sessionId", sessionId)
                put("resourceId", resourceId)
                put("positionMs", positionMs)
                put("durationMs", durationMs)
                put("state", state)
            },
            true,
        )
    }
}

package com.purewo.cyberstream

import android.app.Activity
import android.app.PictureInPictureParams
import android.content.Intent
import android.content.pm.ActivityInfo
import android.os.Build
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.util.Rational
import android.view.View
import android.widget.Button
import android.widget.PopupMenu
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import androidx.media3.common.C
import androidx.media3.common.MediaItem
import androidx.media3.common.Player
import androidx.media3.common.PlaybackException
import androidx.media3.datasource.DefaultHttpDataSource
import androidx.media3.datasource.HttpDataSource
import androidx.media3.exoplayer.ExoPlayer
import androidx.media3.exoplayer.source.DefaultMediaSourceFactory
import androidx.media3.ui.PlayerView
import org.json.JSONArray
import org.json.JSONObject

/**
 * Full-screen Media3 playback surface for CyberStream Android.
 *
 * A session is prepared by TypeScript after it exchanges the authenticated
 * WebView session for short-lived playback tickets. Every resource owns its
 * URL and request headers so source/quality switches retain provider-specific
 * requirements such as the Baidu Netdisk User-Agent.
 */
class PlayerActivity : AppCompatActivity() {
    companion object {
        const val EXTRA_SESSION_JSON = "cyberstream.playback.session"

        const val RESULT_SESSION_ID = "sessionId"
        const val RESULT_RESOURCE_ID = "resourceId"
        const val RESULT_POSITION_MS = "positionMs"
        const val RESULT_DURATION_MS = "durationMs"
        const val RESULT_ENDED = "ended"
        const val RESULT_AUTH_EXPIRED = "authExpired"
        const val RESULT_ERROR = "error"

        private const val PROGRESS_INTERVAL_MS = 10_000L
    }

    private lateinit var player: ExoPlayer
    private lateinit var playerView: PlayerView
    private lateinit var sourceButton: Button
    private lateinit var qualityButton: Button
    private lateinit var session: JSONObject
    private lateinit var sessionId: String
    private var resources = JSONArray()
    private var currentResource: JSONObject? = null
    private var currentVariantId = "direct"
    private var didFinish = false
    private var reachedEnd = false
    private var authExpired = false
    private var lastError: String? = null

    private val handler = Handler(Looper.getMainLooper())
    private val progressReporter = object : Runnable {
        override fun run() {
            emitProgress(if (player.isPlaying) "playing" else "paused")
            handler.postDelayed(this, PROGRESS_INTERVAL_MS)
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        requestedOrientation = ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED

        val rawSession = intent.getStringExtra(EXTRA_SESSION_JSON)
        if (rawSession.isNullOrBlank()) {
            finish()
            return
        }

        try {
            session = JSONObject(rawSession)
            sessionId = session.getString("sessionId")
            resources = session.getJSONArray("resources")
        } catch (error: Exception) {
            Toast.makeText(this, "播放会话无效", Toast.LENGTH_LONG).show()
            finish()
            return
        }

        setContentView(R.layout.activity_player)
        playerView = findViewById(R.id.media_player_view)
        sourceButton = findViewById(R.id.source_button)
        qualityButton = findViewById(R.id.quality_button)

        player = ExoPlayer.Builder(this).build()
        playerView.player = player
        player.addListener(object : Player.Listener {
            override fun onIsPlayingChanged(isPlaying: Boolean) {
                emitProgress(if (isPlaying) "playing" else "paused")
            }

            override fun onPlaybackStateChanged(playbackState: Int) {
                if (playbackState == Player.STATE_ENDED) {
                    reachedEnd = true
                    emitProgress("ended")
                }
            }

            override fun onPlayerError(error: PlaybackException) {
                lastError = error.message
                val cause = error.cause
                if (cause is HttpDataSource.InvalidResponseCodeException && cause.responseCode == 401) {
                    authExpired = true
                    closePlayer()
                    return
                }
                Toast.makeText(this@PlayerActivity, "播放失败：${error.errorCodeName}", Toast.LENGTH_LONG).show()
            }
        })

        sourceButton.setOnClickListener { showSourceMenu(it) }
        qualityButton.setOnClickListener { showQualityMenu(it) }

        val initialId = session.optString("initialResourceId")
        val initial = findResource(initialId) ?: findResourceAt(0)
        if (initial == null) {
            Toast.makeText(this, "没有可播放资源", Toast.LENGTH_LONG).show()
            closePlayer()
            return
        }
        loadResource(initial, session.optLong("startTimeMs", 0L), "direct")
        handler.post(progressReporter)
    }

    private fun findResource(id: String): JSONObject? {
        for (index in 0 until resources.length()) {
            val candidate = resources.optJSONObject(index) ?: continue
            if (candidate.optString("id") == id) return candidate
        }
        return null
    }

    private fun findResourceAt(index: Int): JSONObject? = resources.optJSONObject(index)

    private fun loadResource(resource: JSONObject, positionMs: Long, variantId: String) {
        currentResource = resource
        currentVariantId = variantId
        val variant = findVariant(resource, variantId) ?: resource.optJSONObject("direct")
        if (variant == null || variant.optString("url").isBlank()) {
            Toast.makeText(this, "资源地址不可用", Toast.LENGTH_LONG).show()
            return
        }

        val dataSourceFactory = DefaultHttpDataSource.Factory()
            .setAllowCrossProtocolRedirects(true)
        val userAgent = variant.optString("userAgent")
        if (userAgent.isNotBlank()) dataSourceFactory.setUserAgent(userAgent)
        variant.optJSONObject("headers")?.let { headers ->
            val values = mutableMapOf<String, String>()
            headers.keys().forEach { key -> values[key] = headers.optString(key) }
            if (values.isNotEmpty()) dataSourceFactory.setDefaultRequestProperties(values)
        }

        val itemBuilder = MediaItem.Builder().setUri(variant.getString("url"))
        itemBuilder.setSubtitleConfigurations(buildSubtitles(resource.optJSONArray("subtitles")))
        val source = DefaultMediaSourceFactory(dataSourceFactory).createMediaSource(itemBuilder.build())

        player.setMediaSource(source)
        player.prepare()
        if (positionMs > 0) player.seekTo(positionMs)
        player.play()

        sourceButton.visibility = if (resources.length() > 1) View.VISIBLE else View.GONE
        qualityButton.visibility = if ((resource.optJSONArray("qualities")?.length() ?: 0) > 0) View.VISIBLE else View.GONE
        sourceButton.text = resource.optString("title", "资源")
        qualityButton.text = variant.optString("label", if (variantId == "direct") "原画" else variantId)
    }

    private fun findVariant(resource: JSONObject, id: String): JSONObject? {
        if (id == "direct") return resource.optJSONObject("direct")
        val qualities = resource.optJSONArray("qualities") ?: return null
        for (index in 0 until qualities.length()) {
            val candidate = qualities.optJSONObject(index) ?: continue
            if (candidate.optString("id") == id) return candidate
        }
        return null
    }

    private fun buildSubtitles(subtitles: JSONArray?): List<MediaItem.SubtitleConfiguration> {
        if (subtitles == null) return emptyList()
        val result = mutableListOf<MediaItem.SubtitleConfiguration>()
        for (index in 0 until subtitles.length()) {
            val subtitle = subtitles.optJSONObject(index) ?: continue
            if (!subtitle.optBoolean("supported", true)) continue
            val url = subtitle.optString("url")
            if (url.isBlank()) continue

            val builder = MediaItem.SubtitleConfiguration.Builder(android.net.Uri.parse(url))
            subtitleMimeType(subtitle)?.let { builder.setMimeType(it) }
            subtitle.optString("language").takeIf { it.isNotBlank() }?.let { builder.setLanguage(it) }
            if (subtitle.optBoolean("isDefault", false)) {
                builder.setSelectionFlags(C.SELECTION_FLAG_DEFAULT)
            }
            result.add(builder.build())
        }
        return result
    }

    private fun subtitleMimeType(subtitle: JSONObject): String? {
        subtitle.optString("mimeType").takeIf { it.isNotBlank() }?.let { return it }
        return when (subtitle.optString("format").lowercase()) {
            "vtt" -> "text/vtt"
            "srt" -> "application/x-subrip"
            "ass", "ssa" -> "text/x-ssa"
            else -> null
        }
    }

    private fun showSourceMenu(anchor: View) {
        val popup = PopupMenu(this, anchor)
        for (index in 0 until resources.length()) {
            val resource = resources.optJSONObject(index) ?: continue
            popup.menu.add(0, index, index, resource.optString("title", "资源 ${index + 1}"))
        }
        popup.setOnMenuItemClickListener { item ->
            findResourceAt(item.itemId)?.let { loadResource(it, 0L, "direct") }
            true
        }
        popup.show()
    }

    private fun showQualityMenu(anchor: View) {
        val resource = currentResource ?: return
        val popup = PopupMenu(this, anchor)
        popup.menu.add(0, 0, 0, "原画")
        val qualities = resource.optJSONArray("qualities")
        if (qualities != null) {
            for (index in 0 until qualities.length()) {
                val quality = qualities.optJSONObject(index) ?: continue
                popup.menu.add(0, index + 1, index + 1, quality.optString("label", quality.optString("id")))
            }
        }
        popup.setOnMenuItemClickListener { item ->
            val selected = if (item.itemId == 0) "direct" else qualities?.optJSONObject(item.itemId - 1)?.optString("id") ?: "direct"
            loadResource(resource, player.currentPosition.coerceAtLeast(0L), selected)
            true
        }
        popup.show()
    }

    private fun emitProgress(state: String) {
        val resourceId = currentResource?.optString("id") ?: return
        CyberPlayerPlugin.emitProgress(
            sessionId,
            resourceId,
            player.currentPosition.coerceAtLeast(0L),
            player.duration.takeIf { it > 0 } ?: 0L,
            state,
        )
    }

    override fun onUserLeaveHint() {
        super.onUserLeaveHint()
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O && player.isPlaying && !isInPictureInPictureMode) {
            enterPictureInPictureMode(
                PictureInPictureParams.Builder().setAspectRatio(Rational(16, 9)).build(),
            )
        }
    }

    override fun onBackPressed() {
        closePlayer()
    }

    private fun closePlayer() {
        if (didFinish) return
        didFinish = true
        emitProgress(if (reachedEnd) "ended" else "paused")
        setResult(
            Activity.RESULT_OK,
            Intent()
                .putExtra(RESULT_SESSION_ID, sessionId)
                .putExtra(RESULT_RESOURCE_ID, currentResource?.optString("id"))
                .putExtra(RESULT_POSITION_MS, player.currentPosition.coerceAtLeast(0L))
                .putExtra(RESULT_DURATION_MS, player.duration.takeIf { it > 0 } ?: 0L)
                .putExtra(RESULT_ENDED, reachedEnd)
                .putExtra(RESULT_AUTH_EXPIRED, authExpired)
                .putExtra(RESULT_ERROR, lastError),
        )
        finish()
    }

    override fun onDestroy() {
        handler.removeCallbacksAndMessages(null)
        if (::player.isInitialized) player.release()
        super.onDestroy()
    }
}

