+    private fun configureSeekGesture() {
+        val touchSlop = ViewConfiguration.get(this).scaledTouchSlop.toFloat()
+        playerView.setOnTouchListener { _, event ->
+            when (event.actionMasked) {
+                MotionEvent.ACTION_DOWN -> {
+                    handler.removeCallbacks(hideSeekGestureOverlay)
+                    gestureDownX = event.x
+                    gestureDownY = event.y
+                    gestureStartPositionMs = player.currentPosition.coerceAtLeast(0L)
+                    gestureSeekTargetMs = gestureStartPositionMs
+                    gestureSeeking = false
+                    true
+                }
+
+                MotionEvent.ACTION_MOVE -> {
+                    val deltaX = event.x - gestureDownX
+                    val deltaY = event.y - gestureDownY
+                    if (
+                        !gestureSeeking &&
+                        kotlin.math.abs(deltaX) > touchSlop &&
+                        kotlin.math.abs(deltaX) > kotlin.math.abs(deltaY) * 1.2f
+                    ) {
+                        gestureSeeking = true
+                        playerView.hideController()
+                    }
+                    if (gestureSeeking) updateSeekGesture(deltaX)
+                    true
+                }
+
+                MotionEvent.ACTION_UP -> {
+                    if (gestureSeeking) {
+                        player.seekTo(gestureSeekTargetMs)
+                        handler.removeCallbacks(hideSeekGestureOverlay)
+                        handler.postDelayed(hideSeekGestureOverlay, 650L)
+                    } else if (
+                        kotlin.math.abs(event.x - gestureDownX) <= touchSlop &&
+                        kotlin.math.abs(event.y - gestureDownY) <= touchSlop
+                    ) {
+                        playerView.performClick()
+                    }
+                    gestureSeeking = false
+                    true
+                }
+
+                MotionEvent.ACTION_CANCEL -> {
+                    gestureSeeking = false
+                    seekGestureOverlay.visibility = View.GONE
+                    true
+                }
+
+                else -> true
+            }
+        }
+    }
